def render_situation(templates, situation, subject):
    if situation not in templates:
        raise InvalidSpeechSituation(f"안내 발화 표에 없는 상황입니다: {situation}")
    line = templates[situation]
    if "{subject}" in line:
        if subject is None or not subject.strip():
            raise InvalidSpeechSituation(f"상황이 요구하는 subject가 없습니다: {situation}")
        return line.format(subject=subject)
    return line

